import java.util.StringTokenizer

fun main() {
    val br = System.`in`.bufferedReader()
    val st = StringTokenizer(br.readLine())
    val n = st.nextToken().toInt()
    val m = st.nextToken().toInt()
    var f = 0

    if (n >= m) {
        if (n % 2 == 0) {
            for (i in n / 2..n) {
                if (i % m == 0) {
                    println(i)
                    f = 1
                    break
                }
            }
        } else {
            for (i in n / 2 + 1..n) {
                if (i % m == 0) {
                    println(i)
                    f = 1
                    break
                }
            }
        }
    } else if (m > n) {
        println(-1)
    } else if (f == 0) {
        println(-1)
    }
}

